  "\u7D04": { kanji: "\u7D04", han_viet: "\u01AF\u1EDAC", onyomi: "\u30E4\u30AF", kunyomi: "\u3064\u3065.\u307E\u308B", meaning: "H\u1EB9n \u01B0\u1EDBc, kho\u1EA3ng ch\u1EEBng", radical: "\u7CF8 (M\u1ECBch)", strokes: 9, level: "N3", mnemonic: "Bu\u1ED9c s\u1EE3i ch\u1EC9 (\u7CF8) v\xE0o ng\xF3n tay \u01B0\u1EDBc h\u1EB9n giao k\xE8o." },
  "\u675F": { kanji: "\u675F", han_viet: "TH\xDAC", onyomi: "\u30BD\u30AF", kunyomi: "\u305F\u3070, \u305F\u3070.\u306D\u308B", meaning: "B\xF3, bu\u1ED9c, \u01B0\u1EDBc th\xFAc", radical: "\u6728 (M\u1ED9c)", strokes: 7, level: "N3", mnemonic: "D\xF9ng d\xE2y bu\u1ED9c ch\u1EB7t thanh g\u1ED7 (\u6728) th\xE0nh m\u1ED9t b\xF3." },
