  "\u6A21": { kanji: "\u6A21", han_viet: "M\xD4", onyomi: "\u30E2, \u30DC", kunyomi: "\u2014", meaning: "M\xF4 h\xECnh, quy m\xF4, b\u1EAFt ch\u01B0\u1EDBc", radical: "\u6728 (M\u1ED9c)", strokes: 14, level: "N2", mnemonic: "Khu\xF4n g\u1ED7 (\u6728) \u0111\xFAc ra m\xF4 h\xECnh chu\u1EA9n." },
