app.post("/api/admin/kanjis/ai-fill", requireAuth, requireAdmin, async (req, res) => {
  try {
    const { character } = req.body;
    if (!character) {
      return res.status(400).json({ error: "character is required" });
    }
    const ai = getGeminiClient();
    const prompt = `H\xE3y cung c\u1EA5p th\xF4ng tin chi ti\u1EBFt \u0111\u1EA7y \u0111\u1EE7 cho ch\u1EEF H\xE1n t\u1EF1 (Kanji) sau \u0111\xE2y: "${character}".
Y\xEAu c\u1EA7u:
1. Ngh\u0129a H\xE1n Vi\u1EC7t (ch\u1EC9 l\u1EA5y ngh\u0129a H\xE1n Vi\u1EC7t ch\xEDnh x\xE1c, ch\u1EEF th\u01B0\u1EDDng, v\xED d\u1EE5: "nh\u1EA5t", "nh\u1ECB", "nh\xE2n", "kh\u1EA9u").
2. S\u1ED1 n\xE9t v\u1EBD ch\xEDnh x\xE1c c\u1EE7a ch\u1EEF H\xE1n t\u1EF1 n\xE0y.
3. \xC2m \xD4n (Onyomi): Vi\u1EBFt b\u1EB1ng ch\u1EEF Katakana. N\u1EBFu c\xF3 nhi\u1EC1u \xE2m, ng\u0103n c\xE1ch b\u1EB1ng d\u1EA5u ph\u1EA9y v\xE0 kho\u1EA3ng tr\u1EAFng.
4. \xC2m Kh\xF4n (Kunyomi): Vi\u1EBFt b\u1EB1ng ch\u1EEF Hiragana (k\xE8m theo \u0111u\xF4i okurigana ph\xE2n c\xE1ch b\u1EB1ng d\u1EA5u ch\u1EA5m n\u1EBFu c\u1EA7n, v\xED d\u1EE5: "\u3084.\u3064" ho\u1EB7c "\u3072\u3068.\u3064").
5. T\u1ED1i \u0111a 3 c\u1EE5m t\u1EEB gh\xE9p v\xED d\u1EE5 ti\xEAu bi\u1EC3u v\xE0 h\u1EEFu d\u1EE5ng nh\u1EA5t ch\u1EE9a ch\u1EEF H\xE1n t\u1EF1 n\xE0y. M\u1ED7i c\u1EE5m t\u1EEB gh\xE9p bao g\u1ED3m: T\u1EEB Kanji, C\xE1ch \u0111\u1ECDc Hiragana v\xE0 Ngh\u0129a ti\u1EBFng Vi\u1EC7t r\xF5 r\xE0ng.
6. M\u1EB9o nh\u1EDB (mnemonic): M\u1ED9t c\xE2u ho\u1EB7c m\u1EB9o ng\u1EAFn, d\u1EC5 hi\u1EC3u, h\xF3m h\u1EC9nh li\xEAn t\u01B0\u1EDFng h\xECnh \u1EA3nh ho\u1EB7c chi\u1EBFt t\u1EF1 b\u1ED9 th\u1EE7 \u0111\u1EC3 ng\u01B0\u1EDDi h\u1ECDc d\u1EC5 thu\u1ED9c, nh\u1EDB \u0111\u01B0\u1EE3c c\xE1ch vi\u1EBFt ho\u1EB7c \xFD ngh\u0129a c\u1EE7a ch\u1EEF Kanji n\xE0y (b\u1EB1ng ti\u1EBFng Vi\u1EC7t, t\u1ED1i \u0111a 2 c\xE2u).
7. M\u1ED9t c\xE2u v\xED d\u1EE5 ti\u1EBFng Nh\u1EADt ti\xEAu bi\u1EC3u v\xE0 th\xF4ng d\u1EE5ng s\u1EED d\u1EE5ng ch\u1EEF Kanji n\xE0y.
8. D\u1ECBch ngh\u0129a ti\u1EBFng Vi\u1EC7t c\u1EE7a c\xE2u v\xED d\u1EE5 \u0111\xF3.`;
    const response = await generateGeminiContentWithFallback({
      model: LATEST_GEMINI_MODEL,
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: import_genai2.Type.OBJECT,
          properties: {
            meaningVi: {
              type: import_genai2.Type.STRING,
              description: "Ngh\u0129a H\xE1n Vi\u1EC7t ch\xEDnh x\xE1c c\u1EE7a ch\u1EEF, vi\u1EBFt th\u01B0\u1EDDng, v\xED d\u1EE5 'nh\u1EA5t', 'b\xE1t', 'th\u1EE7y'"
            },
            strokesCount: {
              type: import_genai2.Type.INTEGER,
              description: "S\u1ED1 n\xE9t v\u1EBD ch\xEDnh x\xE1c c\u1EE7a ch\u1EEF H\xE1n t\u1EF1 n\xE0y"
            },
            onyomi: {
              type: import_genai2.Type.STRING,
              description: "\xC2m \xD4n (Onyomi) b\u1EB1ng ch\u1EEF Katakana, ph\xE2n c\xE1ch b\u1EDFi d\u1EA5u ph\u1EA9y n\u1EBFu c\xF3 nhi\u1EC1u \xE2m"
            },
            kunyomi: {
              type: import_genai2.Type.STRING,
              description: "\xC2m Kh\xF4n (Kunyomi) b\u1EB1ng ch\u1EEF Hiragana, ph\xE2n c\xE1ch b\u1EDFi d\u1EA5u ph\u1EA9y n\u1EBFu c\xF3 nhi\u1EC1u \xE2m"
            },
            exampleWords: {
              type: import_genai2.Type.ARRAY,
              description: "T\u1ED1i \u0111a 3 c\u1EE5m t\u1EEB gh\xE9p v\xED d\u1EE5 ti\xEAu bi\u1EC3u nh\u1EA5t ch\u1EE9a ch\u1EEF H\xE1n t\u1EF1 n\xE0y",
              items: {
                type: import_genai2.Type.OBJECT,
                properties: {
                  word: {
                    type: import_genai2.Type.STRING,
                    description: "T\u1EEB gh\xE9p ch\u1EE9a Kanji, v\xED d\u1EE5: '\u516B\u65E5'"
                  },
                  hiragana: {
                    type: import_genai2.Type.STRING,
                    description: "C\xE1ch \u0111\u1ECDc Hiragana c\u1EE7a t\u1EEB gh\xE9p \u0111\xF3, v\xED d\u1EE5: '\u3088\u3046\u304B'"
                  },
                  meaning: {
                    type: import_genai2.Type.STRING,
                    description: "Ngh\u0129a ti\u1EBFng Vi\u1EC7t c\u1EE7a t\u1EEB gh\xE9p \u0111\xF3, v\xED d\u1EE5: 'ng\xE0y m\xF9ng 8'"
                  }
                },
                required: ["word", "hiragana", "meaning"]
              }
            },
            mnemonic: {
              type: import_genai2.Type.STRING,
              description: "C\xE2u chuy\u1EC7n, li\xEAn t\u01B0\u1EDFng h\xECnh \u1EA3nh ho\u1EB7c chi\u1EBFt t\u1EF1 b\u1ED9 th\u1EE7 b\u1EB1ng ti\u1EBFng Vi\u1EC7t \u0111\u1EC3 ng\u01B0\u1EDDi h\u1ECDc d\u1EC5 ghi nh\u1EDB ch\u1EEF Kanji"
            },
            exampleSentence: {
              type: import_genai2.Type.STRING,
              description: "M\u1ED9t c\xE2u v\xED d\u1EE5 ti\u1EBFng Nh\u1EADt c\xF3 s\u1EED d\u1EE5ng ch\u1EEF Kanji n\xE0y, vi\u1EBFt t\u1EF1 nhi\xEAn"
            },
            exampleTranslation: {
              type: import_genai2.Type.STRING,
              description: "D\u1ECBch ngh\u0129a ti\u1EBFng Vi\u1EC7t ch\xEDnh x\xE1c c\u1EE7a c\xE2u v\xED d\u1EE5 ti\u1EBFng Nh\u1EADt tr\xEAn"
            }
          },
          required: ["meaningVi", "strokesCount", "onyomi", "kunyomi", "exampleWords", "mnemonic", "exampleSentence", "exampleTranslation"]
        }
      }
    });
    if (!response.text) {
      throw new Error("Kh\xF4ng nh\u1EADn \u0111\u01B0\u1EE3c ph\u1EA3n h\u1ED3i t\u1EEB m\xF4 h\xECnh AI.");
    }
    const result = JSON.parse(response.text.trim());
    res.json({ success: true, data: result });
  } catch (error) {
    console.error("Error in /api/admin/kanjis/ai-fill:", error);
    res.status(500).json({ error: error.message });
  }
});
