function splitJapaneseSentence(sentence) {
  const clean2 = sentence.trim().replace(/[。！?？]/g, "");
  const particles = /(?<=は|が|を|に|で|と|も|から|まで|、|)/g;
  let parts = clean2.split(particles).map((p) => p.trim()).filter(Boolean);
  if (parts.length < 2) {
    const len = clean2.length;
    const chunkLen = Math.max(2, Math.ceil(len / 3));
    parts = [];
    for (let i = 0; i < len; i += chunkLen) {
      parts.push(clean2.slice(i, i + chunkLen));
    }
  }
  return parts;
}
