function generateOfflineExamGradingAndExplanation(questions, userAnswers = {}, userNotes = {}) {
  const results = questions.map((q, idx) => {
    const qId = q.id || `q_${idx}`;
    let correctIdx = q.correctIndex !== void 0 && q.correctIndex !== null && q.correctIndex >= 0 ? Number(q.correctIndex) : 0;
    const userSelected = userAnswers[qId] !== void 0 ? Number(userAnswers[qId]) : -1;
    const isCorrect = userSelected === correctIdx;
    const userNoteText = (userNotes[qId] || "").trim();
    const hasNote = Boolean(userNoteText);
    let noteAnalysis = {
      userNoteText,
      hasNote,
      isNoteCorrect: true,
      correctionText: userNoteText,
      feedback: hasNote ? "Ghi ch\xFA c\u1EE7a h\u1ECDc vi\xEAn \u0111\xE3 \u0111\u01B0\u1EE3c ghi nh\u1EADn." : ""
    };
    if (hasNote) {
      const lowerNote = userNoteText.toLowerCase();
      const isUncertain = lowerNote.includes("kh\xF4ng ch\u1EAFc") || lowerNote.includes("\u0111o\xE1n") || lowerNote.includes("?");
      const correctOptText2 = q.options && q.options[correctIdx] ? q.options[correctIdx] : "";
      noteAnalysis = {
        userNoteText,
        hasNote: true,
        isNoteCorrect: !isUncertain,
        correctionText: isUncertain ? `\u0110\xEDnh ch\xEDnh: \u0110\xE1p \xE1n ch\xEDnh x\xE1c l\xE0 l\u1EF1a ch\u1ECDn (${correctIdx + 1}): "${correctOptText2}"` : userNoteText,
        feedback: isUncertain ? "\u26A0\uFE0F H\u1ECDc vi\xEAn c\xF2n b\u0103n kho\u0103n c\xE2u n\xE0y. H\xE3y \u0111\u1ED1i chi\u1EBFu t\u1EEB v\u1EF1ng/ng\u1EEF ph\xE1p ch\xEDnh." : "\u2B55 Ghi ch\xFA h\u1ECDc t\u1EADp ph\xE2n t\xEDch t\u1ED1t!"
      };
    }
    const correctOptText = q.options && q.options[correctIdx] ? q.options[correctIdx] : "";
    const explanation = q.explanation || `\u0110\xE1p \xE1n ch\xEDnh x\xE1c l\xE0 l\u1EF1a ch\u1ECDn (${correctIdx + 1}): "${correctOptText}". ${isCorrect ? "B\u1EA1n \u0111\xE3 tr\u1EA3 l\u1EDDi \u0111\xFAng c\xE2u n\xE0y!" : "H\xE3y \u0111\u1ED1i chi\u1EBFu c\xE2u h\u1ECFi v\xE0 \u0111\xE1p \xE1n \u0111\u1EC3 r\xFAt kinh nghi\u1EC7m."}`;
    return {
      id: qId,
      correctIndex: correctIdx,
      isCorrect,
      explanation,
      noteAnalysis
    };
  });
  const correctCount = results.filter((r) => r.isCorrect).length;
  const total = results.length;
  const percentage = Math.round(correctCount / Math.max(1, total) * 100);
  return {
    results,
    teacherSummary: {
      overallComment: `H\u1ECDc vi\xEAn \u0111\xE3 ho\xE0n th\xE0nh b\xE0i thi v\u1EDBi ${correctCount}/${total} c\xE2u ch\xEDnh x\xE1c (${percentage}%). ${percentage >= 80 ? "K\u1EBFt qu\u1EA3 l\xE0m b\xE0i r\u1EA5t t\u1ED1t!" : "H\xE3y ti\u1EBFp t\u1EE5c r\xE8n luy\u1EC7n th\xEAm c\xE1c \u0111i\u1EC3m ng\u1EEF ph\xE1p & t\u1EEB v\u1EF1ng ch\u01B0a v\u1EEFng."}`,
      strengths: [
        percentage >= 70 ? "Ph\u1EA3n x\u1EA1 ch\u1ECDn \u0111\xE1p \xE1n ch\xEDnh x\xE1c cao" : "C\xF3 tinh th\u1EA7n t\u1EF1 luy\u1EC7n thi nghi\xEAm t\xFAc",
        "C\xF3 th\xF3i quen ghi ch\xFA tr\u1EF1c ti\u1EBFp \u0111\u1EC3 ph\xE2n t\xEDch b\xE0i"
      ],
      recommendations: [
        "Xem l\u1EA1i chi ti\u1EBFt c\xE1c c\xE2u l\xE0m sai \u0111\u1EC3 c\u1EE7ng c\u1ED1 ki\u1EBFn th\u1EE9c",
        "T\u1EADp trung ghi nh\u1EDB t\u1EEB v\u1EF1ng v\xE0 m\u1EABu ng\u1EEF ph\xE1p xu\u1EA5t hi\u1EC7n trong \u0111\u1EC1"
      ]
    }
  };
}
